  const g = c.getContext('2d');
  const [r, gg, b] = hexToRgb(color);
  const grad = g.createRadialGradient(128, 128, 0, 128, 128, 128);
  const h = clamp(hardness, 0, 0.99);
  grad.addColorStop(0, `rgba(${r},${gg},${b},1)`);
