    if (!v.loop) { v.loop = true; const step = () => { if (!playing || !l.vref || !state.layers.includes(l)) { v.loop = false; if (l.vref && l.vref.el) l.vref.el.pause(); return; } vrefPaint(l); requestAnimationFrame(step); }; requestAnimationFrame(step); }
