  if (!base && !l.mask) return null;
  const fp = frameParams(l, state.frame);
  if (!fp) return null;
  let cv = l._cv;
  if (!cv || cv.width !== state.w || cv.height !== state.h) cv = l._cv = makeCanvas(state.w, state.h);
  const g = cv.getContext('2d');
  g.clearRect(0, 0, state.w, state.h);
